  ["4f7f24d0"] = "Тіара випадає з боса «{npc:Hydromancer Velratha}».\n\nНеобов’язкове вступне завдання:",
  ["6d0bc59a"] = "Принесіть предмет «{item:Divino-matic Rod}» до НІП «{npc:Chief Engineer Bilgewhizzle}» у місті «{zone:Gadgetzan}».",
  ["c211c240"] = "Жезл випадає з боса «{npc:Sergeant Bly}» після події на піраміді.",
  ["2c07904d"] = "Поговоріть з НІП «{npc:Tran'rek}» у місті «{zone:Gadgetzan}».",
  ["554dccd3"] = "Вступний крок до завдання «{quest:Scarab Shells}».",
  ["4b38636e"] = "Принесіть «{item:Uncracked Scarab Shell}»: 5 шт. НІП «{npc:Tran'rek}» у місті «{zone:Gadgetzan}».",
  ["ee584c42"] = "Маєте завдання «{quest:Tran'rek}» у журналі завдань? Спершу здайте його НІП «{npc:Tran'rek}»: доти ви не зможете взяти завдання «{quest:Scarab Shells}», навіть якщо хтось ним поділиться.",
  ["8d5d2360"] = "Принесіть 20 флаконів «{item:Troll Temper}» до НІП «{npc:Trenton Lighthammer}» у місті «{zone:Gadgetzan}».",
  ["9d68c087"] = "Принесіть першу й другу таблички Мош’ару до НІП «{npc:Yeh'kinya}» у локації «{zone:Tanaris}».",
  ["3bcb18bf"] = "Таблички випадають із босів «{npc:Theka the Martyr}» і «{npc:Hydromancer Velratha}».",
  ["a87e81d8"] = "Принесіть предмет «{item:Nekrum's Medallion}» до НІП «{npc:Thadius Grimshade}» у локації «{zone:Blasted Lands}».",
  ["bdcc9025"] = "Медальйон випадає з боса «{npc:Nekrum Gutchewer}».",
  ["4946cde2"] = "Прочитайте цю табличку, щоб дізнатися ім’я бога-павука цього племені, потім поверніться до НІП «{npc:Master Gadrin}».",
  ["01b1e929"] = "Табличка — у кімнаті НІП «{npc:Theka the Martyr}».",
  ["e37019c9"] = "Розшукайте й зберіть матеріали для книги заклинань, які просив бібліотекар.",
  ["24686738"] = "Убийте боса «{npc:Witch Doctor Zum'rah}» і принесіть предмет «{item:Zum'rah's Head}» до НІП «{npc:Archmage Lan'dalock}» у місті «{zone:Dalaran}».",
  ["e60fdfa4"] = "Убийте боса «{npc:Witch Doctor Zum'rah}» і принесіть предмет «{item:Zum'rah's Head}» до НІП «{npc:Mazu'kon}» у локації «{zone:Mulgore}».",
  ["e268a948"] = "Принесіть «{zone:Venom Bottle}» аптекареві в місцевості «{zone:Tarren Mill}».",
  ["7c479dc0"] = "Принесіть предмет «{item:Undamaged Venom Sac}» до НІП «{npc:Apothecary Lydon}» у місцевості «{zone:Tarren Mill}».",
  ["71df3fcd"] = "Поговоріть з НІП «{npc:Master Gadrin}» у селищі «{zone:Sen'jin Village}».",
  ["09b4599c"] = "Перевірте клітки в обох селищах Сухокорів, потім поверніться до НІП «{npc:Gryphon Master Talonaxe}».",
  ["00e5d48c"] = "Перевірте вершину місцевості «{zone:The Altar of Zul}», потім поверніться до НІП «{npc:Gryphon Master Talonaxe}».",
  ["25566d61"] = "Принесіть предмет «{item:Sharpbeak's Feather}» до НІП «{npc:Thadius Grimshade}» у локації «{zone:Blasted Lands}».",
  ["3504ba35"] = "Захопіть духів 3 верескунів у локації «{zone:Feralas}», потім поверніться до НІП «{npc:Yeh'kinya}» у місцевості «{zone:Steamwheedle Port}».",
  ["fb33a03a"] = "Прочитайте отримані настанови. Потім здобудьте предмет «{item:Amulet of Union}» у підземеллі «{zone:Maraudon}» і поверніть його до НІП «{npc:Centaur Pariah}» на півдні локації «{zone:Desolace}».",
  ["b10b01a0"] = "Зберіть «{item:Shadowshard Fragment}»: 10 шт. у підземеллі «{zone:Maraudon}» і віднесіть їх до НІП «{npc:Uthel'nay}» у місті «{zone:Orgrimmar}».",
  ["09fe0165"] = "Тіньоскалки — елементалі в зовнішніх печерах із фіолетовими кристалами. Можна виконати, не заходячи в підземелля.",
  ["f4956e87"] = "Зберіть «{item:Shadowshard Fragment}»: 10 шт. у підземеллі «{zone:Maraudon}» і віднесіть їх до НІП «{npc:Archmage Tervosh}» у Тераморі на узбережжі локації «{zone:Dustwallow Marsh}».",
  ["7e0c35c2"] = "Наповніть флакон «{item:Coated Cerulean Vial}» у басейні з помаранчевими кристалами в підземеллі «{zone:Maraudon}». Використайте «{item:Filled Cerulean Vial}» на ліанах, щоб змусити зіпсованих паростків «{npc:Noxxious Scion}» вийти. Зцілте 8 рослин, убиваючи паростків «{npc:Noxxious Scion}», потім поверніться до НІП «{npc:Vark Battlescar}» у селищі «{zone:Shadowprey Village}».",
  ["5109d569"] = "Наповніть флакон «{item:Coated Cerulean Vial}» у басейні з помаранчевими кристалами в підземеллі «{zone:Maraudon}». Використайте «{item:Filled Cerulean Vial}» на ліанах, щоб змусити зіпсованих паростків «{npc:Noxxious Scion}» вийти. Зцілте 8 рослин, убиваючи паростків «{npc:Noxxious Scion}», потім поверніться до НІП «{npc:Talendria}» на заставі «{zone:Nijel's Point}».",
  ["145be8d1"] = "Зберіть «{item:Theradric Crystal Carving}»: 25 шт. для НІП «{npc:Willow}» у локації «{zone:Desolace}».",
  ["5693156a"] = "Будь-яка істота в підземеллі «{zone:Maraudon}» може залишити потрібні для завдання предмети.",
  ["c9c17b5f"] = "Здобудьте обидві частини предмета «{item:Scepter of Celebras}»: «{item:Celebrian Rod}» і «{item:Celebrian Diamond}». Знайдіть спосіб поговорити з НІП, пов’язаним зі скіпетром.",
  ["bcc41ed9"] = "Предмет «{item:Celebrian Rod}» випадає з боса «{npc:Noxxion}», а «{item:Celebrian Diamond}» — з боса «{npc:Lord Vyletongue}».",
  ["81803436"] = "Допоможіть НІП «{npc:Celebras the Redeemed}», поки він створює «{item:Scepter of Celebras}». Поговоріть із ним, коли ритуал завершиться.",
  ["fd299527"] = "Здолайте боса «{npc:Celebras the Cursed}» там, де сходяться шляхи, і здайте завдання «{quest:Legends of Maraudon}» НІП «{npc:Celebras the Redeemed}», потім допоможіть із ритуалом і знову поговоріть із ним, щоб отримати скіпетр.",
  ["9e5080dc"] = "Убийте боса «{npc:Princess Theradras}» і поверніться до НІП «{npc:Selendra}» біля селища «{zone:Shadowprey Village}» у локації «{zone:Desolace}».",
  ["56f7ec57"] = "Убийте боса «{npc:Princess Theradras}» у внутрішній печері.",
  ["2e7a7cd4"] = "Убийте боса «{npc:Princess Theradras}» і поверніться до НІП «{npc:Keeper Marandis}» на заставі «{zone:Nijel's Point}» у локації «{zone:Desolace}».",
  ["bab6b202"] = "Вирушайте до підземелля «{zone:Maraudon}» і здобудьте предмет «{item:Vial of Earth Song Water}», потім загасіть ним полум’я цього НІП у місцевості «{zone:Forlorn Gardens}».",
  ["49b26440"] = "Повернувшись у місцевість «{zone:Forlorn Gardens}», використайте флакон на палаючому дереві поруч із цим НІП, а не на ньому самому. Потім він відправляє вас до місцевості «{zone:Bristleback Retreat}», а це веде до наступного завдання у підземеллі «{zone:Razorfen Downs}».",
  ["c31190bb"] = "Здобудьте кристал «{item:An'she's Radiance}» у підземеллі «{zone:Maraudon}» і віднесіть його до НІП «{npc:Olana Brighthoof}» у локації «{zone:Mulgore}».",
  ["8a706267"] = "За водоспадом «{zone:Earth Song Falls}» знайдіть залу з яскраво-білими кристалами, яку охороняють велетні. Візьміть «{item:An'she's Radiance}» з кристала біля найвищої частини зали. Нагорода: 300 репутації із Земляним Кільцем і 200 репутації з містом «{zone:Thunder Bluff}».",
  ["46cd35fa"] = "Знайдіть НІП «Ремулос» у локації «{zone:Moonglade}» і віддайте йому предмет «{item:Seed of Life}».",
  ["4d22b897"] = "НІП «{npc:Zaetar's Spirit}» з’являється після смерті боса «{npc:Princess Theradras}».",
  ["3f1d087a"] = "Знайдіть предмет «{item:Talisman of Kazdor}» у підземеллі «{zone:Zul'Farrak}». Потім віднесіть його до НІП «{npc:Fahrad}» у місцевості «{zone:Ravenholdt Manor}». Виконати завдання потрібно самостійно.",
  ["a2c2914e"] = "Розбійники: виконайте завдання «{quest:The Manor, Ravenholdt}», «{quest:The Horn of Xelthos}» і «{quest:The Eye of Bhossca}». На 45-му рівні поверніться до великого міста по лист від НІП «{npc:Fahrad}». У місцевості «{zone:Ravenholdt Manor}» виконайте наступне завдання ланцюжка, поговоривши з НІП «{npc:Fahrad}»; тоді він пропонує «{item:Talisman of Kazdor}». До підземелля «{zone:Zul'Farrak}» заходьте самі.",
  ["f6d8af64"] = "Віднесіть «{item:Seal of Ravenholdt}» до НІП «{npc:Fahrad}» у місцевості «{zone:Ravenholdt Manor}», захованій у пагорбах «{zone:Hillsbrad}».",
  ["71b9fd46"] = "Спершу вивчіть вміння, що виявляє пастки: щоб пройти випробування, достатньо пройти повз скриню-пастку в печерному проході до маєтку (цього навчає й НІП «{npc:Fahrad}»).",
  ["805360f9"] = "Отримайте лист, що починає це завдання. Орда: у тренера розбійників виберіть варіант, де ви просите лист. Альянс: у начальника розвідки в місті «{zone:Stormwind}».",
  ["135d0144"] = "Поговоріть з НІП «{npc:Fahrad}», коли будете готові вислухати його план.",
  ["f62721fb"] = "На 45-му рівні, коли всі доручення виконано, вирушайте до столиці: лист від НІП «{npc:Fahrad}» у поштовій скриньці відправить вас до місцевості «{zone:Ravenholdt Manor}». Прийміть завдання, ще раз поговоріть з НІП «{npc:Fahrad}» і здайте його йому.",
  ["660e16d4"] = "Скористайтеся підказками із записки, щоб дізнатися, де шукати магічні компоненти для ритуалу. Для цього вам знадобиться допомога союзників.",
  ["b0603492"] = "Завдання паладина Альянсу. Як його відкрити: «{item:Bloody Missive}», потім завдання про пошуки (у місцевості «{zone:Emerald Sanctuary}» спершу взаємодійте з конем, а тоді йдіть за його слідом), потім поговоріть із конем і з НІП у локації «{zone:Felwood}»: той видає завдання про особливі матеріали. Його частини — з «{zone:Felwood}», «{zone:Maraudon}», «{zone:Blackrock Depths}» і «{zone:Hillsbrad Foothills}».",
  ["724362f2"] = "Довгий ланцюжок завдань: частина сюжету паладина Альянсу.",
  ["a1c33064"] = "Поговоріть з НІП «{npc:Katherine the Pure}» у «{zone:Cathedral of Light}» в місті «{zone:Stormwind}».",
  ["561142d6"] = "Вирушайте до вказаного міста й знайдіть загадкового торговця.",
  ["b3ffe2a5"] = "Поговоріть з цим НІП, щоб дізнатися більше.",
  ["3e3a0955"] = "Якщо ви в групі з іншими паладинами, лише один із вас зможе підібрати записку, яку впускає цей НІП («{item:Bloody Missive}»). Якщо ви її не отримали, не здавайте це завдання трактирнику: скасуйте його й почніть знову.",
  ["a43f1c2a"] = "Віднесіть послання до НІП «{npc:Katherine the Pure}» у «{zone:Cathedral of Light}» в місті «{zone:Stormwind}».",
  ["f123e54d"] = "Пошукайте сліди того, кого ви розшукуєте, у місцевості «{zone:Emerald Sanctuary}» в локації «{zone:Felwood}».",
  ["564edb5b"] = "Ці гриби також можна зібрати поза підземеллям.",
  ["44024f47"] = "Предмет «{item:Tablet of Ryun'eh}» лежить у скрині поза підземеллям.",
  ["a3741ba4"] = "Енергетичні камені також можуть випадати з елітних дворфів поза підземеллям.",
  ["1859d771"] = "Предмет «{item:Krom Stoutarm's Treasure}» лежить у його скрині поза підземеллям.",
  ["3c7d88da"] = "Предмет «{item:Garrett Family Treasure}» лежить у родинній скрині поза підземеллям.",
  ["ab06ef5f"] = "Виконайте це завдання до вбивства останнього боса.",
  ["77091e57"] = "Це виконується ПОЗА підземеллям.",
  ["d23653fc"] ="У місцевості «{zone:Emerald Sanctuary}» спершу взаємодійте з конем (51.0, 81.8), а тоді йдіть за його слідом у локації «{zone:Felwood}» до нього (45.0, 52.0). Потім поговоріть з ним і з НІП: той видає завдання про особливі матеріали.",
  ["d8fc7554"] = "Можна вбити НІП «{npc:Qiaga the Keeper}» на верхівці вівтаря, щоб здобути предмет «{item:Sacred Mallet}».",
  ["be8f86fd"] = "Три з п’яти самоцвітів — у ханів ПОЗА підземеллям, у зовнішніх печерах.",
  ["d45f5e54"] = "Використайте предмет «{item:Filled Cerulean Vial}» на цих рослинах (ліанах). Їх не можна клацнути чи взяти в ціль, тож виглядайте їх у помаранчевому крилі.",
}
